const BATCH = 8;
const ORDER = new Map(REST.map((p, i) => [p, i]));
const at = p => new URL(p, self.registration.scope).href;
const fresh = p => new Request(at(p), { cache: 'reload' });
// the island-world caches made before this worker's own, oldest first (caches.keys() is in creation order). A cache made
// after it belongs to a newer version installing while this worker is still active: never touched here. Other names,
// such as the three old apps' caches, are never touched either. Without this worker's cache: none.
const earlier = keys => keys.slice(0, Math.max(0, keys.indexOf(CACHE))).filter(k => k.startsWith(PREFIX));

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL.map(fresh))).then(() => self.skipWaiting()));
});

// the latest earlier cache stays (assets not fetched again yet are served from it), older ones go
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(earlier(keys).slice(0, -1).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});

// background fetching of REST: one run at a time; a warm that comes during a run only moves its prefixes to the front
let warming = null;
let prefer = [];
const rank = p => { const i = prefer.findIndex(x => p.startsWith(x)); return i < 0 ? prefer.length : i; };
async function warm() {
  const c = await caches.open(CACHE);
  const have = new Set((await c.keys()).map(r => r.url));
  const todo = REST.filter(p => !have.has(at(p)));
  while (todo.length) {
    todo.sort((a, b) => rank(a) - rank(b) || ORDER.get(a) - ORDER.get(b));
    const batch = todo.splice(0, BATCH);
    await Promise.all(batch.map(async p => {
      try {
        if (await c.match(at(p))) return;
        const r = await fetch(fresh(p));
        if (r.ok) await c.put(at(p), r);
      } catch { /* this one later: the next warm fetches what is missing */ }
    }));
  }
  const now = new Set((await c.keys()).map(r => r.url));
  if (REST.every(p => now.has(at(p)))) await Promise.all(earlier(await caches.keys()).map(k => caches.delete(k)));
}
self.addEventListener('message', e => {
  const d = e.data || {};
  if (d.type !== 'warm') return;
  const asked = Array.isArray(d.prefer) ? d.prefer.filter(x => typeof x === 'string') : [];
  prefer = [...asked, ...prefer.filter(x => !asked.includes(x))];
  if (!warming) warming = warm().catch(() => {}).then(() => { warming = null; });
  e.waitUntil(warming);
});

// this cache first, then the network (a good answer is kept), then the earlier island-world caches, then for a page
// the cached entrance (sent to its own address, so its relative addresses resolve)
async function answer(req) {
  const c = await caches.open(CACHE);
  const hit = await c.match(req, { ignoreSearch: true });
  if (hit) return hit;
  try {
    const r = await fetch(req);
    if (r.ok) { const u = new URL(req.url); u.search = ''; await c.put(u.href, r.clone()).catch(() => {}); }
    return r;
  } catch (err) {
    for (const k of earlier(await caches.keys()).reverse()) {
      const old = await (await caches.open(k)).match(req, { ignoreSearch: true });
      if (old) return old;
    }
    if (req.mode === 'navigate' && await c.match(at('index.html'))) return Response.redirect(at('index.html'), 302);
    throw err;
  }
}
self.addEventListener('fetch', e => {
  const req = e.request;
  // only this site's own addresses (inside the scope); anything else on the same host is left to the browser
  if (req.method !== 'GET' || !req.url.startsWith(self.registration.scope)) return;
  e.respondWith(answer(req));
});
